import { beforeEach, vi } from 'vitest';

// Mock fetch for API calls during client tests.
// In test environment there is no backend server, so we intercept
// the specific endpoints the app uses and return valid mock data.
// The passthrough target is captured once at module load: capturing it
// inside beforeEach grabs the previous test's spy (vi.spyOn returns the
// existing spy), making the default branch recurse on itself as soon as
// a test fetches a URL outside the mocked set.
const originalFetch = globalThis.fetch.bind(globalThis);

beforeEach(() => {
	vi.spyOn(globalThis, 'fetch').mockImplementation(
		async (input: RequestInfo | URL, init?: RequestInit) => {
			const url = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url;

			// Mock server props endpoint
			if (url.includes('/server')) {
				return new Response(
					JSON.stringify({
						git_branch: 'test',
						git_commit: 'test',
						mode: 'router',
						version: 'test'
					}),
					{ headers: { 'Content-Type': 'application/json' }, status: 200 }
				);
			}

			// Mock models list endpoint
			if (/\/v1\/models|\/models\b/.test(url)) {
				return new Response(
					JSON.stringify({
						data: [
							{
								created: 0,
								id: 'test-model.gguf',
								in_cache: false,
								meta: {},
								object: 'model',
								owned_by: 'llamacpp',
								path: 'models/test-model.gguf',
								status: { value: 'unloaded' }
							}
						],
						models: [
							{
								details: {},
								model: 'test-model.gguf',
								name: 'Test Model'
							}
						],
						object: 'list'
					}),
					{ headers: { 'Content-Type': 'application/json' }, status: 200 }
				);
			}

			// Mock /props endpoint (used for modalities)
			if (url.includes('/props')) {
				return new Response(
					JSON.stringify({
						default_generation_settings: { n_ctx: 2048 }
					}),
					{ headers: { 'Content-Type': 'application/json' }, status: 200 }
				);
			}

			// Mock /tools endpoint (used for built-in tools list)
			if (url.includes('/tools')) {
				return new Response(JSON.stringify([]), {
					headers: { 'Content-Type': 'application/json' },
					status: 200
				});
			}

			// Default: use real fetch
			return originalFetch(input, init);
		}
	);
});

import argparse
import json
import requests
import logging
import sys

handler = logging.StreamHandler(sys.stdout)
handler.terminator = ""   # ← no newline
logging.basicConfig(level=logging.INFO, format='%(message)s', handlers=[handler])
logger = logging.getLogger("server-test-model")


def run_query(url, messages, tools=None, stream=False, tool_choice=None):
    payload = {
        "messages": messages,
        "stream": stream,
        "max_tokens": 5000,
    }
    if tools:
        payload["tools"] = tools
    if tool_choice:
        payload["tool_choice"] = tool_choice

    try:
        response = requests.post(url, json=payload, stream=stream)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        if e.response is not None:
            logger.info(f"Response error: {e} for {e.response.content}\n")
        else:
            logger.info(f"Error connecting to server: {e}\n")
        return None

    full_content = ""
    reasoning_content = ""
    tool_calls = []

    if stream:
        logger.info(f"--- Streaming response (Tools: {bool(tools)}) ---\n")
        for line in response.iter_lines():
            if line:
                decoded_line = line.decode("utf-8")
                if decoded_line.startswith("data: "):
                    data_str = decoded_line[6:]
                    if data_str == "[DONE]":
                        break
                    try:
                        data = json.loads(data_str)
                        if "choices" in data and len(data["choices"]) > 0:
                            delta = data["choices"][0].get("delta", {})

                            # Content
                            content_chunk = delta.get("content", "")
                            if content_chunk:
                                full_content += content_chunk
                                logger.info(content_chunk)

                            # Reasoning
                            reasoning_chunk = delta.get("reasoning_content", "")
                            if reasoning_chunk:
                                reasoning_content += reasoning_chunk
                                logger.info(f"\x1B[3m{reasoning_chunk}\x1B[0m")

                            # Tool calls
                            if "tool_calls" in delta:
                                for tc in delta["tool_calls"]:
                                    index = tc.get("index")
                                    if index is not None:
                                        while len(tool_calls) <= index:
                                            # Using "function" as type default but could be flexible
                                            tool_calls.append(
                                                {
                                                    "id": "",
                                                    "type": "function",
                                                    "function": {
                                                        "name": "",
                                                        "arguments": "",
                                                    },
                                                }
                                            )

                                        if "id" in tc:
                                            tool_calls[index]["id"] += tc["id"]
                                        if "function" in tc:
                                            if "name" in tc["function"]:
                                                tool_calls[index]["function"][
                                                    "name"
                                                ] += tc["function"]["name"]
                                            if "arguments" in tc["function"]:
                                                tool_calls[index]["function"][
                                                    "arguments"
                                                ] += tc["function"]["arguments"]

                    except json.JSONDecodeError:
                        logger.info(f"Failed to decode JSON: {data_str}\n")
        logger.info("\n--- End of Stream ---\n")
    else:
        logger.info(f"--- Non-streaming response (Tools: {bool(tools)}) ---\n")
        data = response.json()
        if "choices" in data and len(data["choices"]) > 0:
            message = data["choices"][0].get("message", {})
            full_content = message.get("content", "")
            reasoning_content = message.get("reasoning_content", "")
            tool_calls = message.get("tool_calls", [])
            logger.info(full_content)
        logger.info("--- End of Response ---\n")

    return {
        "content": full_content,
        "reasoning_content": reasoning_content,
        "tool_calls": tool_calls,
    }


def test_chat(url, stream):
    logger.info(f"\n=== Testing Chat (Stream={stream}) ===\n")
    messages = [{"role": "user", "content": "What is the capital of France?"}]
    result = run_query(url, messages, stream=stream)

    if result:
        if result["content"]:
            logger.info("PASS: Output received.\n")
        else:
            logger.info("WARN: No content received (valid if strict tool call, but unexpected here).\n")

        if result.get("reasoning_content"):
            logger.info(f"INFO: Reasoning content detected ({len(result['reasoning_content'])} chars).\n")
        else:
            logger.info("INFO: No reasoning content detected (Standard model behavior).\n")
    else:
        logger.info("FAIL: No result.\n")


def test_tool_call(url, stream):
    logger.info(f"\n=== Testing Tool Call (Stream={stream}) ===\n")
    messages = [
        {
            "role": "user",
            "content": "What is the weather in London? Please use the get_weather tool.",
        }
    ]
    tools = [
        {
            "type": "function",
            "function": {
                "name": "get_weather",
                "description": "Get the current weather in a given location",
                "parameters": {
                    "type": "object",
                    "properties": {
                        "location": {
                            "type": "string",
                            "description": "The city and state, e.g. San Francisco, CA",
                        },
                        "unit": {"type": "string", "enum": ["celsius", "fahrenheit"]},
                    },
                    "required": ["location"],
                },
            },
        }
    ]

    result = run_query(url, messages, tools=tools, tool_choice="auto", stream=stream)

    if result:
        tcs = result.get("tool_calls")
        if tcs and len(tcs) > 0:
            logger.info("PASS: Tool calls detected.")
            for tc in tcs:
                func = tc.get("function", {})
                logger.info(f"  Tool: {func.get('name')}, Args: {func.get('arguments')}\n")
        else:
            logger.info(f"FAIL: No tool calls. Content: {result['content']}\n")

        if result.get("reasoning_content"):
            logger.info(
                f"INFO: Reasoning content detected during tool call ({len(result['reasoning_content'])} chars).\n"
            )
    else:
        logger.info("FAIL: Query failed.\n")


def main():
    parser = argparse.ArgumentParser(description="Test llama-server functionality.")
    parser.add_argument("--host", default="localhost", help="Server host")
    parser.add_argument("--port", default=8080, type=int, help="Server port")
    args = parser.parse_args()

    base_url = f"http://{args.host}:{args.port}/v1/chat/completions"
    logger.info(f"Testing server at {base_url}\n")

    # Non-streaming tests
    test_chat(base_url, stream=False)
    test_tool_call(base_url, stream=False)

    # Streaming tests
    test_chat(base_url, stream=True)
    test_tool_call(base_url, stream=True)


if __name__ == "__main__":
    main()

import pytest
from openai import OpenAI
from utils import *
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

server = ServerPreset.tinyllama2()

TEST_API_KEY = "[REDACTED]"

@pytest.fixture(autouse=True)
def create_server():
    global server
    server = ServerPreset.tinyllama2()
    server.api_key = [REDACTED]


@pytest.mark.parametrize("endpoint", ["/health"])
def test_access_public_endpoint(endpoint: str):
    global server
    server.start()
    res = server.make_request("GET", endpoint)
    assert res.status_code == 200
    assert "error" not in res.body


def test_access_static_assets_without_api_key():
    """Static web UI assets should not require API key authentication (issue #21229)"""
    global server
    server.start()
    for path in ["/", "/sw.js", "/manifest.webmanifest", "/_app/version.json"]:
        res = server.make_request("GET", path)
        assert res.status_code == 200, f"Expected 200 for {path}, got {res.status_code}"


@pytest.mark.parametrize("api_key", [None, "invalid-key"])
def test_incorrect_api_key(api_key: str):
    global server
    server.start()
    res = server.make_request("POST", "/completions", data={
        "prompt": "I believe the meaning of life is",
    }, headers={
        "Authorization": f"Bearer {api_key}" if api_key else None,
    })
    assert res.status_code == 401
    assert "error" in res.body
    assert res.body["error"]["type"] == "authentication_error"


def test_correct_api_key():
    global server
    server.start()
    res = server.make_request("POST", "/completions", data={
        "prompt": "I believe the meaning of life is",
    }, headers={
        "Authorization": f"Bearer {TEST_API_KEY}",
    })
    assert res.status_code == 200
    assert "error" not in res.body
    assert "content" in res.body


def test_correct_api_key_anthropic_header():
    global server
    server.start()
    res = server.make_request("POST", "/completions", data={
        "prompt": "I believe the meaning of life is",
    }, headers={
        "X-Api-Key": [REDACTED],
    })
    assert res.status_code == 200
    assert "error" not in res.body
    assert "content" in res.body


def test_openai_library_correct_api_key():
    global server
    server.start()
    client = OpenAI(api_key=[REDACTED], base_url=f"http://{server.server_host}:{server.server_port}")
    res = client.chat.completions.create(
        model="gpt-3.5-turbo",
        messages=[
            {"role": "system", "content": "You are a chatbot."},
            {"role": "user", "content": "What is the meaning of life?"},
        ],
    )
    assert len(res.choices) == 1


@pytest.mark.parametrize("origin,cors_header,cors_header_value", [
    ("localhost", "Access-Control-Allow-Origin", "localhost"),
    ("web.mydomain.fr", "Access-Control-Allow-Origin", "web.mydomain.fr"),
    ("origin", "Access-Control-Allow-Credentials", "true"),
    ("web.mydomain.fr", "Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS"),
    ("web.mydomain.fr", "Access-Control-Allow-Headers", "*"),
])
def test_cors_options(origin: str, cors_header: str, cors_header_value: str):
    global server
    server.start()
    res = server.make_request("OPTIONS", "/completions", headers={
        "Origin": origin,
        "Access-Control-Request-Method": "POST",
        "Access-Control-Request-Headers": "Authorization",
    })
    assert res.status_code == 200
    assert cors_header in res.headers
    assert res.headers[cors_header] == cors_header_value


@pytest.mark.parametrize("origin", [
    "http://localhost",
    "http://localhost:8080",
    "http://127.0.0.1",
    "http://127.0.0.1:3000",
    "http://[::1]",
    "http://[::1]:3000",
])
def test_cors_origins_localhost_reflects(origin: str):
    global server
    server = ServerPreset.router()
    server.cors_origins = "localhost"
    server.start()
    res = server.make_request("OPTIONS", "/completions", headers={
        "Origin": origin,
        "Access-Control-Request-Method": "POST",
        "Access-Control-Request-Headers": "Authorization",
    })
    assert res.status_code == 200
    assert res.headers["Access-Control-Allow-Origin"] == origin


@pytest.mark.parametrize("origin", [
    "http://web.mydomain.fr",
    "http://evil.com",
    "http://notlocalhost",
    "http://localhost.evil.com",
])
def test_cors_origins_localhost_rejects(origin: str):
    global server
    server = ServerPreset.router()
    server.cors_origins = "localhost"
    server.start()
    res = server.make_request("OPTIONS", "/completions", headers={
        "Origin": origin,
        "Access-Control-Request-Method": "POST",
        "Access-Control-Request-Headers": "Authorization",
    })
    assert res.status_code == 200
    assert "Access-Control-Allow-Origin" not in res.headers


def test_cors_origins_defaults_to_localhost_with_tools_enabled():
    global server
    server = ServerPreset.router()
    server.server_tools = "all"
    server.start()
    res = server.make_request("OPTIONS", "/completions", headers={
        "Origin": "http://localhost:8080",
        "Access-Control-Request-Method": "POST",
        "Access-Control-Request-Headers": "Authorization",
    })
    assert res.status_code == 200
    assert res.headers["Access-Control-Allow-Origin"] == "http://localhost:8080"

    res = server.make_request("OPTIONS", "/completions", headers={
        "Origin": "http://evil.com",
        "Access-Control-Request-Method": "POST",
        "Access-Control-Request-Headers": "Authorization",
    })
    assert res.status_code == 200
    assert "Access-Control-Allow-Origin" not in res.headers


def test_cors_proxy_only_forwards_explicit_proxy_headers():
    class CaptureHeadersHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            self.server.captured_headers = dict(self.headers)
            self.send_response(200)
            self.end_headers()
            self.wfile.write(b"ok")

        def log_message(self, format, *args):
            pass

    target = ThreadingHTTPServer(("127.0.0.1", 0), CaptureHeadersHandler)
    target.captured_headers = {}
    target_thread = threading.Thread(target=target.serve_forever, daemon=True)
    target_thread.start()

    try:
        server = ServerPreset.tinyllama2()
        server.api_key = [REDACTED]
        server.ui_mcp_proxy = True
        server.start()

        res = server.make_request("GET", f"/cors-proxy?url=http://127.0.0.1:{target.server_port}/capture", headers={
            "Authorization": f"Bearer {TEST_API_KEY}",
            "Proxy-Authorization": "Basic secret",
            "X-Api-Key": [REDACTED],
            "Cookie": "session=secret",
            "x-llama-server-proxy-header-accept": "application/json",
            "x-llama-server-proxy-header-authorization": "Bearer explicit",
        })

        assert res.status_code == 200
        captured = {key.lower(): value for key, value in target.captured_headers.items()}
        assert captured["accept"] == "application/json"
        assert captured["authorization"] == "Bearer explicit"
        assert "proxy-authorization" not in captured
        assert "x-api-key" not in captured
        assert "cookie" not in captured
    finally:
        target.shutdown()
        target.server_close()


@pytest.mark.parametrize(
    "media_path, image_url, success",
    [
        (None,             "file://mtmd/test-1.jpeg",    False), # disabled media path, should fail
        ("../../../tools", "file://mtmd/test-1.jpeg",    True),
        ("../../../tools", "file:////mtmd//test-1.jpeg", True),  # should be the same file as above
        ("../../../tools", "file://mtmd/notfound.jpeg",  False), # non-existent file
        ("../../../tools", "file://../mtmd/test-1.jpeg", False), # no directory traversal
    ]
)
def test_local_media_file(media_path, image_url, success,):
    server = ServerPreset.tinygemma3()
    server.media_path = media_path
    server.start()
    res = server.make_request("POST", "/chat/completions", data={
        "max_tokens": 1,
        "messages": [
            {"role": "user", "content": [
                {"type": "text", "text": "test"},
                {"type": "image_url", "image_url": {
                    "url": image_url,
                }},
            ]},
        ],
    })
    if success:
        assert res.status_code == 200
    else:
        assert res.status_code == 400
